/**
 * rollbackService.ts - Service for undoing code changes
 *
 * Features:
 * - Rollback changes via change journal API
 * - Batch rollback for multiple changes
 * - Rollback validation and conflict detection
 * - Error handling and recovery
 */

import type { RollbackRequest, RollbackResult, FileChange } from '../types/subagent';

/**
 * API base URL
 */
const API_BASE = 'http://localhost:3000/api';

/**
 * Rollback service for undoing changes
 */
export class RollbackService {
  /**
   * Rollback a single change by ID
   */
  async rollbackChange(changeId: string): Promise<RollbackResult> {
    try {
      const response = await fetch(`${API_BASE}/changes/${changeId}/rollback`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to rollback change');
      }

      const data = await response.json();

      return {
        success: true,
        filesRestored: [data.path],
        errors: [],
        timestamp: Date.now(),
      };
    } catch (error) {
      return {
        success: false,
        filesRestored: [],
        errors: [error instanceof Error ? error.message : 'Unknown error'],
        timestamp: Date.now(),
      };
    }
  }

  /**
   * Rollback multiple changes (batch operation)
   */
  async rollbackBatch(request: RollbackRequest): Promise<RollbackResult> {
    const results: RollbackResult = {
      success: true,
      filesRestored: [],
      errors: [],
      timestamp: Date.now(),
    };

    for (const changeId of request.changeIds) {
      const result = await this.rollbackChange(changeId);

      if (result.success) {
        results.filesRestored.push(...result.filesRestored);
      } else {
        results.success = false;
        results.errors.push(...result.errors);
      }
    }

    return results;
  }

  /**
   * Rollback all changes for a specific execution
   */
  async rollbackExecution(
    executionId: string,
    changes: FileChange[]
  ): Promise<RollbackResult> {
    // Extract change IDs from file changes
    const changeIds = changes
      .map(c => c.changeId)
      .filter((id): id is string => id !== undefined);

    if (changeIds.length === 0) {
      return {
        success: false,
        filesRestored: [],
        errors: ['No valid change IDs found'],
        timestamp: Date.now(),
      };
    }

    return this.rollbackBatch({
      executionId,
      changeIds,
      reason: 'Rolling back execution',
    });
  }

  /**
   * Validate if a rollback can be performed safely
   */
  async validateRollback(changeId: string): Promise<{
    valid: boolean;
    conflicts: string[];
    warnings: string[];
  }> {
    try {
      // Get the change details
      const response = await fetch(`${API_BASE}/changes/${changeId}`);

      if (!response.ok) {
        return {
          valid: false,
          conflicts: ['Change not found in journal'],
          warnings: [],
        };
      }

      const change = await response.json();

      // Check for conflicts with newer changes
      const allChangesResponse = await fetch(`${API_BASE}/changes}?path=${change.path}`);
      if (allChangesResponse.ok) {
        const allChanges = await allChangesResponse.json();
        const newerChanges = allChanges.changes.filter(
          (c: any) => c.path === change.path && c.timestamp > change.timestamp
        );

        if (newerChanges.length > 0) {
          return {
            valid: false,
            conflicts: [
              `File has ${newerChanges.length} newer change(s) after this one`,
              'Rolling back may cause conflicts with those changes',
            ],
            warnings: [
              'Consider rolling back newer changes first',
              'Or manually review the file after rollback',
            ],
          };
        }
      }

      return {
        valid: true,
        conflicts: [],
        warnings: [],
      };
    } catch (error) {
      return {
        valid: false,
        conflicts: [error instanceof Error ? error.message : 'Validation failed'],
        warnings: [],
      };
    }
  }

  /**
   * Get all changes from the journal
   */
  async getAllChanges(options?: {
    limit?: number;
    offset?: number;
    path?: string;
  }): Promise<any[]> {
    try {
      const params = new URLSearchParams();
      if (options?.limit) params.append('limit', options.limit.toString());
      if (options?.offset) params.append('offset', options.offset.toString());
      if (options?.path) params.append('path', options.path);

      const response = await fetch(`${API_BASE}/changes?${params.toString()}`);

      if (!response.ok) {
        throw new Error('Failed to fetch changes');
      }

      const data = await response.json();
      return data.changes || [];
    } catch (error) {
      console.error('Error fetching changes:', error);
      return [];
    }
  }

  /**
   * Get changes for a specific file
   */
  async getChangesForFile(filePath: string): Promise<any[]> {
    return this.getAllChanges({ path: filePath });
  }
}

// Singleton instance
let rollbackServiceInstance: RollbackService | null = null;

/**
 * Get or create the singleton rollback service instance
 */
export function getRollbackService(): RollbackService {
  if (!rollbackServiceInstance) {
    rollbackServiceInstance = new RollbackService();
  }
  return rollbackServiceInstance;
}

/**
 * Enhanced DiagramView - Integrates Focus Mode, Search, and Context Menus
 */

import React, { useCallback, useState } from 'react';
import {
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  NodeTypes,
  Connection,
  addEdge,
  useNodesState,
  useEdgesState,
  BackgroundVariant,
  Node,
  Edge,
  OnSelectionChangeParams
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { useDiagramStore } from '../stores/useDiagramStore';
import { applyAutoLayout } from '../utils/diagramLayout';
import DiagramNode from './DiagramNode';
import { DiagramNodeData } from '../types/diagram';
import FocusMode from './FocusMode';
import { getSearchIndexer, SearchResultItem } from '../utils/searchIndexer';
import { useContextMenu, getNodeContextMenuItems, getCanvasContextMenuItems } from './ContextMenu';

// Register custom node type
const nodeTypes: NodeTypes = {
  custom: DiagramNode as any
};

// Custom edge styles
const defaultEdgeOptions = {
  animated: true,
  style: { stroke: '#64748b', strokeWidth: 2 }
};

export default function DiagramViewEnhanced() {
  const {
    nodes: storeNodes,
    edges: storeEdges,
    showMiniMap,
    addNode,
    updateNode,
    addEdge: addStoreEdge,
    deleteNode,
    fitView
  } = useDiagramStore();

  const [nodes, setNodes, onNodesChange] = useNodesState(storeNodes as Node[]);
  const [edges, setEdges, onEdgesChange] = useEdgesState(storeEdges);
  const [focusedNodeId, setFocusedNodeId] = useState<string | null>(null);
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);

  // Context menu
  const { showContextMenu, ContextMenu } = useContextMenu();

  // Sync store state with local state
  React.useEffect(() => {
    setNodes(storeNodes as Node[]);
  }, [storeNodes, setNodes]);

  React.useEffect(() => {
    setEdges(storeEdges);
  }, [storeEdges, setEdges]);

  // Update search index when data changes
  React.useEffect(() => {
    const indexer = getSearchIndexer();

    // Convert diagram nodes to graph data format for search
    const graphData = {
      nodes: storeNodes.map(n => ({
        id: n.id,
        group: 0,
        label: n.data.label,
        type: (n.data as DiagramNodeData).type || 'process'
      })),
      links: storeEdges.map(e => ({
        source: e.source as string,
        target: e.target as string,
        value: 1
      }))
    };

    indexer.buildIndex(graphData);
  }, [storeNodes, storeEdges]);

  // Handle new connections
  const onConnect = useCallback(
    (connection: Connection) => {
      const newEdge = {
        ...connection,
        id: `e${connection.source}-${connection.target}`,
        animated: true,
        style: { stroke: '#64748b', strokeWidth: 2 }
      };
      setEdges((eds) => addEdge(connection, eds));
      addStoreEdge(newEdge);
    },
    [setEdges, addStoreEdge]
  );

  // Handle node updates
  const onNodeDoubleClick = useCallback(
    (_: any, node: Node) => {
      updateNode(node.id, { editable: true });
    },
    [updateNode]
  );

  // Handle selection change
  const onSelectionChange = useCallback(
    ({ nodes: selectedNodes }: OnSelectionChangeParams) => {
      if (selectedNodes && selectedNodes.length > 0) {
        const selectedId = selectedNodes[0].id;
        setSelectedNodeId(selectedId);
      } else {
        setSelectedNodeId(null);
      }
    },
    []
  );

  // Apply auto-layout
  const handleAutoLayout = useCallback(() => {
    const layouted = applyAutoLayout(storeNodes, storeEdges, {
      direction: 'TB',
      nodeSpacing: 100,
      rankSpacing: 150
    });
    setNodes(layouted.nodes as Node[]);
  }, [storeNodes, storeEdges, setNodes]);

  // Add new node
  const handleAddNode = useCallback(() => {
    const newNodeId = `node-${Date.now()}`;
    const newNode = {
      id: newNodeId,
      type: 'custom' as const,
      position: { x: Math.random() * 400 + 100, y: Math.random() * 300 + 100 },
      data: {
        label: 'New Node',
        type: 'process' as const,
        description: 'Add description',
        color: '#3b82f6',
        editable: true
      }
    };
    addNode(newNode);
  }, [addNode]);

  // Handle node context menu
  const handleNodeContextMenu = useCallback(
    (event: React.MouseEvent, node: Node) => {
      event.preventDefault();
      const items = getNodeContextMenuItems(node.id, {
        onFocus: () => setFocusedNodeId(node.id),
        onEdit: () => updateNode(node.id, { editable: true }),
        onDelete: () => {
          deleteNode(node.id);
          if (focusedNodeId === node.id) {
            setFocusedNodeId(null);
          }
        },
        onDuplicate: () => {
          const newNodeId = `node-${Date.now()}`;
          const newNode = {
            ...node,
            id: newNodeId,
            position: {
              x: node.position.x + 50,
              y: node.position.y + 50
            }
          };
          addNode(newNode);
        },
        onConnect: () => {
          // Trigger connection mode
          setSelectedNodeId(node.id);
        }
      });
      showContextMenu(event.clientX, event.clientY, items);
    },
    [focusedNodeId, deleteNode, addNode, updateNode, showContextMenu]
  );

  // Handle canvas context menu
  const handlePaneContextMenu = useCallback(
    (event: React.MouseEvent) => {
      event.preventDefault();
      const items = getCanvasContextMenuItems({
        onCreateNode: handleAddNode,
        onAutoLayout: handleAutoLayout,
        onFitView: () => fitView(),
        onZoomIn: () => {
          // Handled by React Flow controls
        },
        onZoomOut: () => {
          // Handled by React Flow controls
        },
        onResetZoom: () => {
          // Handled by React Flow controls
        }
      });
      showContextMenu(event.clientX, event.clientY, items);
    },
    [handleAddNode, handleAutoLayout, fitView, showContextMenu]
  );

  // Clear focus
  const handleClearFocus = useCallback(() => {
    setFocusedNodeId(null);
  }, []);

  // MiniMap node colors
  const minimapNodeColor = useCallback((node: Node) => {
    const data = node.data as DiagramNodeData;
    return data.color || '#6b7280';
  }, []);

  // Filter nodes based on focus
  const filteredNodes = React.useMemo(() => {
    if (!focusedNodeId) return nodes;

    // Find connected nodes
    const connectedIds = new Set([focusedNodeId]);
    edges.forEach((edge) => {
      if (edge.source === focusedNodeId) {
        connectedIds.add(edge.target as string);
      }
      if (edge.target === focusedNodeId) {
        connectedIds.add(edge.source as string);
      }
    });

    return nodes.filter((n) => connectedIds.has(n.id));
  }, [nodes, focusedNodeId, edges]);

  // Filter edges based on visible nodes
  const filteredEdges = React.useMemo(() => {
    if (!focusedNodeId) return edges;

    const visibleNodeIds = new Set(filteredNodes.map((n) => n.id));
    return edges.filter((e) =>
      visibleNodeIds.has(e.source as string) && visibleNodeIds.has(e.target as string)
    );
  }, [edges, filteredNodes]);

  return (
    <div className="w-full h-full bg-slate-950 relative">
      {/* Focus Mode Banner */}
      {focusedNodeId && (
        <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20 flex items-center gap-3 bg-cyan-600/90 backdrop-blur border border-cyan-400 rounded-lg px-4 py-2 shadow-lg">
          <span className="text-sm font-semibold text-white">
            Focus: {nodes.find(n => n.id === focusedNodeId)?.data?.label || focusedNodeId}
          </span>
          <span className="text-xs text-cyan-100">
            ({filteredNodes.length} nodes)
          </span>
          <button
            onClick={handleClearFocus}
            className="ml-2 px-2 py-1 bg-white/20 hover:bg-white/30 text-white text-xs rounded transition-colors"
          >
            Clear
          </button>
        </div>
      )}

      {/* Toolbar */}
      <div className="absolute top-4 left-4 z-10 flex gap-2">
        <button
          onClick={handleAutoLayout}
          className="px-4 py-2 bg-cyan-600 hover:bg-cyan-500 text-white text-sm font-medium rounded-lg shadow-lg transition-colors flex items-center gap-2"
        >
          <span>📐</span> Auto Layout
        </button>
        <button
          onClick={handleAddNode}
          className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-medium rounded-lg shadow-lg transition-colors flex items-center gap-2"
        >
          <span>➕</span> Add Node
        </button>
      </div>

      {/* React Flow Canvas */}
      <ReactFlow
        nodes={filteredNodes.map((node) => ({
          ...node,
          data: {
            ...node.data,
            onLabelChange: (id: string, newLabel: string) => {
              updateNode(id, { label: newLabel });
            }
          }
        }))}
        edges={filteredEdges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        onNodeDoubleClick={onNodeDoubleClick}
        onNodeContextMenu={handleNodeContextMenu}
        onPaneContextMenu={handlePaneContextMenu}
        onSelectionChange={onSelectionChange}
        nodeTypes={nodeTypes}
        defaultEdgeOptions={defaultEdgeOptions}
        fitView
        className="bg-slate-950"
      >
        <Background
          variant={BackgroundVariant.Dots}
          gap={16}
          size={1}
          color="#334155"
        />
        <Controls
          className="!bg-slate-900 !border !border-slate-700"
          showZoom={true}
          showFitView={true}
          showInteractive={true}
        />
        {showMiniMap && (
          <MiniMap
            nodeColor={minimapNodeColor}
            nodeStrokeWidth={3}
            nodeBorderRadius={8}
            pannable
            zoomable
            className="!bg-slate-900 !border !border-slate-700"
          />
        )}
      </ReactFlow>

      {/* Instructions */}
      <div className="absolute bottom-4 left-4 z-10 bg-slate-900/90 backdrop-blur border border-slate-700 rounded-lg p-3 text-xs text-slate-400">
        <div className="font-semibold text-slate-300 mb-1">Controls:</div>
        <ul className="space-y-1">
          <li>• Right-click for context menu</li>
          <li>• Double-click to edit labels</li>
          <li>• Cmd+F to focus selected node</li>
          <li>• Cmd+K for quick actions</li>
        </ul>
      </div>

      {/* Context Menu */}
      <ContextMenu />
    </div>
  );
}

/**
 * rollbackService.test.ts - Tests for rollback service
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { RollbackService } from './rollbackService';

// Mock fetch
global.fetch = vi.fn();

describe('RollbackService', () => {
  let service: RollbackService;

  beforeEach(() => {
    service = new RollbackService();
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  describe('rollbackChange', () => {
    it('should successfully rollback a change', async () => {
      const mockResponse = {
        ok: true,
        json: async () => ({ path: '/test/file.ts', message: 'Change rolled back' }),
      };

      vi.mocked(global.fetch).mockResolvedValueOnce(mockResponse as any);

      const result = await service.rollbackChange('change-id-123');

      expect(result.success).toBe(true);
      expect(result.filesRestored).toEqual(['/test/file.ts']);
      expect(result.errors).toEqual([]);
    });

    it('should handle rollback failure', async () => {
      const mockResponse = {
        ok: false,
        json: async () => ({ error: 'Change not found' }),
      };

      vi.mocked(global.fetch).mockResolvedValueOnce(mockResponse as any);

      const result = await service.rollbackChange('invalid-id');

      expect(result.success).toBe(false);
      expect(result.filesRestored).toEqual([]);
      expect(result.errors).toContain('Change not found');
    });
  });

  describe('rollbackBatch', () => {
    it('should rollback multiple changes', async () => {
      const mockResponse = {
        ok: true,
        json: async () => ({ path: '/test/file.ts', message: 'Change rolled back' }),
      };

      vi.mocked(global.fetch).mockResolvedValue(mockResponse as any);

      const result = await service.rollbackBatch({
        executionId: 'exec-123',
        changeIds: ['change-1', 'change-2', 'change-3'],
        reason: 'Test rollback',
      });

      expect(result.success).toBe(true);
      expect(result.filesRestored.length).toBe(3);
      expect(global.fetch).toHaveBeenCalledTimes(3);
    });

    it('should handle partial failures in batch rollback', async () => {
      vi.mocked(global.fetch)
        .mockResolvedValueOnce({
          ok: true,
          json: async () => ({ path: '/test/file1.ts', message: 'Success' }),
        } as any)
        .mockResolvedValueOnce({
          ok: false,
          json: async () => ({ error: 'Not found' }),
        } as any)
        .mockResolvedValueOnce({
          ok: true,
          json: async () => ({ path: '/test/file3.ts', message: 'Success' }),
        } as any);

      const result = await service.rollbackBatch({
        executionId: 'exec-123',
        changeIds: ['change-1', 'change-2', 'change-3'],
      });

      expect(result.success).toBe(false);
      expect(result.filesRestored.length).toBe(2);
      expect(result.errors.length).toBe(1);
    });
  });

  describe('validateRollback', () => {
    it('should validate safe rollback', async () => {
      vi.mocked(global.fetch)
        .mockResolvedValueOnce({
          ok: true,
          json: async () => ({
            id: 'change-123',
            path: '/test/file.ts',
            timestamp: 1000,
          }),
        } as any)
        .mockResolvedValueOnce({
          ok: true,
          json: async () => ({ changes: [] }),
        } as any);

      const result = await service.validateRollback('change-123');

      expect(result.valid).toBe(true);
      expect(result.conflicts).toEqual([]);
      expect(result.warnings).toEqual([]);
    });

    it('should detect conflicts with newer changes', async () => {
      vi.mocked(global.fetch)
        .mockResolvedValueOnce({
          ok: true,
          json: async () => ({
            id: 'change-123',
            path: '/test/file.ts',
            timestamp: 1000,
          }),
        } as any)
        .mockResolvedValueOnce({
          ok: true,
          json: async () => ({
            changes: [
              { path: '/test/file.ts', timestamp: 2000 },
              { path: '/test/file.ts', timestamp: 3000 },
            ],
          }),
        } as any);

      const result = await service.validateRollback('change-123');

      expect(result.valid).toBe(false);
      expect(result.conflicts.length).toBeGreaterThan(0);
      expect(result.conflicts[0]).toContain('2 newer change');
    });
  });

  describe('getAllChanges', () => {
    it('should fetch all changes', async () => {
      const mockChanges = [
        { id: 'change-1', path: '/file1.ts', timestamp: 1000 },
        { id: 'change-2', path: '/file2.ts', timestamp: 2000 },
      ];

      vi.mocked(global.fetch).mockResolvedValueOnce({
        ok: true,
        json: async () => ({ changes: mockChanges, count: 2 }),
      } as any);

      const changes = await service.getAllChanges();

      expect(changes).toEqual(mockChanges);
    });

    it('should fetch changes with filters', async () => {
      vi.mocked(global.fetch).mockResolvedValueOnce({
        ok: true,
        json: async () => ({ changes: [], count: 0 }),
      } as any);

      await service.getAllChanges({ limit: 10, offset: 5, path: '/test' });

      expect(global.fetch).toHaveBeenCalledWith(
        expect.stringContaining('limit=10&offset=5&path=%2Ftest')
      );
    });
  });

  describe('getChangesForFile', () => {
    it('should fetch changes for specific file', async () => {
      const mockChanges = [
        { id: 'change-1', path: '/test/file.ts', timestamp: 1000 },
      ];

      vi.mocked(global.fetch).mockResolvedValueOnce({
        ok: true,
        json: async () => ({ changes: mockChanges, count: 1 }),
      } as any);

      const changes = await service.getChangesForFile('/test/file.ts');

      expect(changes).toEqual(mockChanges);
      expect(global.fetch).toHaveBeenCalledWith(
        expect.stringContaining('path=%2Ftest%2Ffile.ts')
      );
    });
  });
});

