/**
 * subagentOrchestrator.test.ts - Tests for subagent orchestrator
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { SubagentOrchestrator } from './subagentOrchestrator';
import type { ExecutionRequest } from '../types/subagent';

describe('SubagentOrchestrator', () => {
  let orchestrator: SubagentOrchestrator;

  beforeEach(() => {
    orchestrator = new SubagentOrchestrator({
      maxConcurrent: 3,
      defaultTimeout: 5000,
      retryAttempts: 1,
      retryDelay: 100,
    });
  });

  afterEach(() => {
    orchestrator.shutdown();
  });

  describe('submit', () => {
    it('should submit a task and return execution ID', async () => {
      const request: ExecutionRequest = {
        taskId: 'task-1',
        taskTitle: 'Rename variable',
        taskDescription: 'Rename foo to bar',
        files: ['src/test.ts'],
        priority: 'medium',
      };

      const executionId = await orchestrator.submit(request);

      expect(executionId).toBeTruthy();
      expect(typeof executionId).toBe('string');

      const execution = orchestrator.getExecution(executionId);
      expect(execution).toBeDefined();
      expect(execution?.status).toBe('queued');
    });

    it('should queue tasks when pool is full', async () => {
      const request: ExecutionRequest = {
        taskId: 'task-1',
        taskTitle: 'Test task',
        taskDescription: 'Test',
        files: [],
        priority: 'medium',
      };

      // Submit 5 tasks (more than maxConcurrent of 3)
      const executionIds = await Promise.all([
        orchestrator.submit({ ...request, taskId: 'task-1' }),
        orchestrator.submit({ ...request, taskId: 'task-2' }),
        orchestrator.submit({ ...request, taskId: 'task-3' }),
        orchestrator.submit({ ...request, taskId: 'task-4' }),
        orchestrator.submit({ ...request, taskId: 'task-5' }),
      ]);

      const stats = orchestrator.getStatistics();
      expect(stats.activeExecutions).toBeLessThanOrEqual(3);
      expect(stats.queuedExecutions).toBeGreaterThan(0);
    });
  });

  describe('cancel', () => {
    it('should cancel a queued execution', () => {
      const request: ExecutionRequest = {
        taskId: 'task-1',
        taskTitle: 'Test task',
        taskDescription: 'Test',
        files: [],
        priority: 'low',
      };

      // Use a custom config with maxConcurrent: 0 to force queueing
      const testOrchestrator = new SubagentOrchestrator({
        maxConcurrent: 0,
        defaultTimeout: 5000,
      });

      return testOrchestrator.submit(request).then(executionId => {
        const cancelled = testOrchestrator.cancel(executionId);
        expect(cancelled).toBe(true);

        const execution = testOrchestrator.getExecution(executionId);
        expect(execution?.status).toBe('cancelled');

        testOrchestrator.shutdown();
      });
    });

    it('should cancel an active execution', () => {
      const request: ExecutionRequest = {
        taskId: 'task-1',
        taskTitle: 'Test task',
        taskDescription: 'Test',
        files: [],
        priority: 'high',
      };

      return orchestrator.submit(request).then(executionId => {
        // Wait a bit for execution to start
        return new Promise<void>((resolve) => {
          setTimeout(() => {
            const cancelled = orchestrator.cancel(executionId);
            expect(cancelled).toBe(true);

            const execution = orchestrator.getExecution(executionId);
            expect(execution?.status).toMatch(/cancelled|failed/);
            resolve();
          }, 100);
        });
      });
    });
  });

  describe('getStatistics', () => {
    it('should return accurate statistics', async () => {
      const request: ExecutionRequest = {
        taskId: 'task-1',
        taskTitle: 'Test task',
        taskDescription: 'Test',
        files: [],
        priority: 'medium',
      };

      await orchestrator.submit(request);

      const stats = orchestrator.getStatistics();

      expect(stats.totalExecutions).toBeGreaterThan(0);
      expect(stats.activeExecutions).toBeGreaterThanOrEqual(0);
      expect(stats.queuedExecutions).toBeGreaterThanOrEqual(0);
      expect(stats.completedExecutions).toBeGreaterThanOrEqual(0);
      expect(stats.failedExecutions).toBeGreaterThanOrEqual(0);
    });
  });

  describe('event callbacks', () => {
    it('should emit events for status changes', async () => {
      const events: any[] = [];

      orchestrator.onEvent((event) => {
        events.push(event);
      });

      const request: ExecutionRequest = {
        taskId: 'task-1',
        taskTitle: 'Test task',
        taskDescription: 'Test',
        files: [],
        priority: 'medium',
      };

      const executionId = await orchestrator.submit(request);

      // Should have received a status_change event
      const statusEvents = events.filter(e => e.type === 'status_change');
      expect(statusEvents.length).toBeGreaterThan(0);
      expect(statusEvents[0].executionId).toBe(executionId);
    });
  });

  describe('priority handling', () => {
    it('should prioritize high priority tasks', async () => {
      const events: any[] = [];

      orchestrator.onEvent((event) => {
        events.push(event);
      });

      // Submit low priority first
      await orchestrator.submit({
        taskId: 'low-1',
        taskTitle: 'Low priority',
        taskDescription: 'Test',
        files: [],
        priority: 'low',
      });

      // Then high priority
      await orchestrator.submit({
        taskId: 'high-1',
        taskTitle: 'High priority',
        taskDescription: 'Test',
        files: [],
        priority: 'critical',
      });

      // High priority should be processed first
      // (This is a simplified test - real testing would require synchronization)
      expect(events.length).toBeGreaterThan(0);
    });
  });

  describe('timeout handling', () => {
    it('should timeout long-running executions', () => {
      const testOrchestrator = new SubagentOrchestrator({
        maxConcurrent: 1,
        defaultTimeout: 100, // Very short timeout
      });

      const request: ExecutionRequest = {
        taskId: 'task-1',
        taskTitle: 'Long running task',
        taskDescription: 'Test',
        files: [],
        priority: 'medium',
      };

      return testOrchestrator.submit(request).then(executionId => {
        return new Promise<void>((resolve) => {
          setTimeout(() => {
            const execution = testOrchestrator.getExecution(executionId);
            expect(execution?.status).toMatch(/failed|cancelled/);
            expect(execution?.error).toBeDefined();
            testOrchestrator.shutdown();
            resolve();
          }, 200);
        });
      });
    });
  });
});

/**
 * GraphViewWithFeatures - Complete integration example
 *
 * Demonstrates how to use all Phase 4 features together:
 * - Focus Mode
 * - Search Modal
 * - Quick Actions Menu
 * - Keyboard Shortcuts
 * - Context Menus
 */

import React, { useState, useCallback, useEffect } from 'react';
import { GraphData, Node } from '../types';
import { getSearchIndexer, SearchResultItem } from '../utils/searchIndexer';
import { useKeyboardShortcuts, getDefaultShortcuts } from '../hooks/useKeyboardShortcuts';
import SearchModal from './SearchModal';
import QuickActionsMenu from './QuickActionsMenu';
import { useContextMenu, getCanvasContextMenuItems } from './ContextMenu';

interface GraphViewWithFeaturesProps {
  children: (props: {
    focusedNodeId: string | null;
    onNodeClick: (nodeId: string) => void;
    searchQuery: string;
  }) => React.ReactNode;
  graphData: GraphData;
  selectedNodeId?: string | null;
  onNodeSelect?: (nodeId: string | null) => void;
  onAutoLayout?: () => void;
  onCreateNode?: () => void;
  onFitView?: () => void;
  onToggleMiniMap?: () => void;
  onExport?: () => void;
}

/**
 * GraphViewWithFeatures Component
 *
 * Wrapper that adds all Phase 4 features to any graph view
 */
const GraphViewWithFeatures: React.FC<GraphViewWithFeaturesProps> = ({
  children,
  graphData,
  selectedNodeId: externalSelectedNodeId,
  onNodeSelect,
  onAutoLayout,
  onCreateNode,
  onFitView,
  onToggleMiniMap,
  onExport
}) => {
  // State
  const [focusedNodeId, setFocusedNodeId] = useState<string | null>(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isQuickActionsOpen, setIsQuickActionsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResultItem[]>([]);

  // Context menu
  const { showContextMenu, ContextMenu } = useContextMenu();

  // Update search index when graph data changes
  useEffect(() => {
    const indexer = getSearchIndexer();
    indexer.buildIndex(graphData);
  }, [graphData]);

  // Perform search when query changes
  useEffect(() => {
    const indexer = getSearchIndexer();
    const results = indexer.search(searchQuery);
    setSearchResults(results);
  }, [searchQuery]);

  // Keyboard shortcuts
  const shortcuts = getDefaultShortcuts({
    onOpenQuickActions: () => {
      setIsQuickActionsOpen(true);
      setIsSearchOpen(false);
      setSearchQuery('');
    },
    onFocusNode: () => {
      if (externalSelectedNodeId) {
        setFocusedNodeId(externalSelectedNodeId);
      }
    },
    onClearFocus: () => {
      setFocusedNodeId(null);
    },
    onCloseModals: () => {
      setIsSearchOpen(false);
      setIsQuickActionsOpen(false);
    }
  });

  useKeyboardShortcuts(shortcuts, true);

  // Handle node click
  const handleNodeClick = useCallback((nodeId: string) => {
    onNodeSelect?.(nodeId);
  }, [onNodeSelect]);

  // Handle search result selection
  const handleSearchResultSelect = useCallback((item: SearchResultItem) => {
    setFocusedNodeId(item.nodeId);
    onNodeSelect?.(item.nodeId);
    setIsSearchOpen(false);
    setIsQuickActionsOpen(false);
    setSearchQuery('');
  }, [onNodeSelect]);

  // Handle canvas context menu
  const handleCanvasContextMenu = useCallback(
    (event: React.MouseEvent) => {
      event.preventDefault();
      const items = getCanvasContextMenuItems({
        onCreateNode: () => {
          onCreateNode?.();
          setIsQuickActionsOpen(false);
        },
        onAutoLayout: () => {
          onAutoLayout?.();
          setIsQuickActionsOpen(false);
        },
        onFitView: () => {
          onFitView?.();
          setIsQuickActionsOpen(false);
        },
        onZoomIn: () => {
          // Handled by React Flow
        },
        onZoomOut: () => {
          // Handled by React Flow
        },
        onResetZoom: () => {
          // Handled by React Flow
        }
      });
      showContextMenu(event.clientX, event.clientY, items);
    },
    [onCreateNode, onAutoLayout, onFitView, showContextMenu]
  );

  return (
    <div
      className="relative w-full h-full"
      onContextMenu={handleCanvasContextMenu}
    >
      {/* Render the graph view with features */}
      {children({
        focusedNodeId,
        onNodeClick: handleNodeClick,
        searchQuery
      })}

      {/* Focus Mode Banner */}
      {focusedNodeId && (
        <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20 flex items-center gap-3 bg-cyan-600/90 backdrop-blur border border-cyan-400 rounded-lg px-4 py-2 shadow-lg">
          <span className="text-sm font-semibold text-white">
            Focus: {graphData.nodes.find(n => n.id === focusedNodeId)?.label || focusedNodeId}
          </span>
          <button
            onClick={() => setFocusedNodeId(null)}
            className="ml-2 px-2 py-1 bg-white/20 hover:bg-white/30 text-white text-xs rounded transition-colors"
            title="Clear focus (Cmd+Shift+F)"
          >
            Clear
          </button>
        </div>
      )}

      {/* Keyboard shortcuts hint */}
      <div className="absolute bottom-4 right-4 z-10 bg-slate-900/90 backdrop-blur border border-slate-700 rounded-lg px-3 py-2 text-xs text-slate-500">
        <div className="font-semibold text-slate-300 mb-1">Shortcuts:</div>
        <div className="space-y-0.5">
          <div><kbd className="bg-slate-700 px-1 rounded">Cmd+K</kbd> Quick actions</div>
          <div><kbd className="bg-slate-700 px-1 rounded">Cmd+F</kbd> Focus node</div>
          <div><kbd className="bg-slate-700 px-1 rounded">ESC</kbd> Close modals</div>
        </div>
      </div>

      {/* Search Modal */}
      <SearchModal
        isOpen={isSearchOpen}
        onClose={() => setIsSearchOpen(false)}
        results={searchResults}
        query={searchQuery}
        onQueryChange={setSearchQuery}
        onSelectResult={handleSearchResultSelect}
      />

      {/* Quick Actions Menu */}
      <QuickActionsMenu
        isOpen={isQuickActionsOpen}
        onClose={() => setIsQuickActionsOpen(false)}
        searchResults={searchResults}
        searchQuery={searchQuery}
        onSearchQueryChange={setSearchQuery}
        onSearchResultSelect={handleSearchResultSelect}
        onFocusNode={() => {
          if (externalSelectedNodeId) {
            setFocusedNodeId(externalSelectedNodeId);
          }
          setIsQuickActionsOpen(false);
        }}
        onClearFocus={() => {
          setFocusedNodeId(null);
          setIsQuickActionsOpen(false);
        }}
        onCreateNode={() => {
          onCreateNode?.();
          setIsQuickActionsOpen(false);
        }}
        onAutoLayout={() => {
          onAutoLayout?.();
          setIsQuickActionsOpen(false);
        }}
        onToggleMiniMap={() => {
          onToggleMiniMap?.();
          setIsQuickActionsOpen(false);
        }}
        onExport={() => {
          onExport?.();
          setIsQuickActionsOpen(false);
        }}
      />

      {/* Context Menu */}
      <ContextMenu />
    </div>
  );
};

export default GraphViewWithFeatures;

/**
 * Integration test: End-to-end rename variable task
 *
 * This test simulates the complete workflow:
 * 1. Create a task to rename a variable
 * 2. Execute the task
 * 3. Monitor progress
 * 4. Verify file changes
 * 5. Test rollback
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { SubagentOrchestrator, getOrchestrator } from '../../src/services/subagentOrchestrator';
import { getRollbackService } from '../../src/services/rollbackService';
import type { ExecutionRequest, FileChange } from '../../src/types/subagent';

describe('End-to-End: Rename Variable Task', () => {
  const orchestrator = getOrchestrator({
    maxConcurrent: 1,
    defaultTimeout: 30000,
  });
  const rollbackService = getRollbackService();

  let executionId: string;
  let executionResult: any;

  beforeAll(async () => {
    // Ensure server is running
    const response = await fetch('http://localhost:3000/api/health');
    expect(response.ok).toBe(true);
  });

  it('should execute a simple rename variable task', async () => {
    // Step 1: Submit the task
    const request: ExecutionRequest = {
      taskId: 'rename-var-001',
      taskTitle: 'Rename "foo" to "bar" in utils.ts',
      taskDescription: 'Rename the variable "foo" to "bar" to improve code clarity',
      files: ['src/utils.ts'],
      priority: 'medium',
      timeout: 30000,
    };

    executionId = await orchestrator.submit(request);

    expect(executionId).toBeTruthy();
    console.log('Task submitted with execution ID:', executionId);

    // Step 2: Monitor execution
    await new Promise<void>((resolve) => {
      const unsubscribe = orchestrator.onEvent((event) => {
        if (event.executionId === executionId) {
          const result = orchestrator.getExecution(executionId);
          console.log(`Status: ${result?.status}, Progress: ${result?.progress}%`);

          if (result?.status === 'completed' || result?.status === 'failed') {
            executionResult = result;
            unsubscribe();
            resolve();
          }
        }
      });
    });

    // Step 3: Verify completion
    expect(executionResult.status).toBe('completed');
    expect(executionResult.progress).toBe(100);
    expect(executionResult.changes.length).toBeGreaterThan(0);
    console.log('Execution completed successfully');
  });

  it('should have generated valid file changes', () => {
    expect(executionResult.changes).toBeDefined();
    expect(executionResult.changes.length).toBeGreaterThan(0);

    const firstChange = executionResult.changes[0] as FileChange;
    expect(firstChange.path).toBeTruthy();
    expect(firstChange.changeType).toBeTruthy();
    expect(['create', 'update', 'delete']).toContain(firstChange.changeType);

    console.log('File changes:', executionResult.changes);
  });

  it('should have a valid diff for changes', () => {
    const firstChange = executionResult.changes[0] as FileChange;

    if (firstChange.changeType !== 'delete') {
      expect(firstChange.diff).toBeTruthy();
      expect(typeof firstChange.diff).toBe('string');

      // Verify diff format (should have @@ markers)
      expect(firstChange.diff).toContain('@@');

      console.log('Diff preview:', firstChange.diff?.substring(0, 200));
    }
  });

  it('should have recorded change in journal', async () => {
    const firstChange = executionResult.changes[0] as FileChange;

    if (firstChange.changeId) {
      // Verify change exists in journal
      const response = await fetch(
        `http://localhost:3000/api/changes/${firstChange.changeId}`
      );

      expect(response.ok).toBe(true);
      const change = await response.json();
      expect(change.id).toBe(firstChange.changeId);
      expect(change.path).toBe(firstChange.path);

      console.log('Change recorded in journal:', change.id);
    }
  });

  it('should be able to rollback the change', async () => {
    const firstChange = executionResult.changes[0] as FileChange;

    if (firstChange.changeId) {
      // Validate rollback first
      const validation = await rollbackService.validateRollback(firstChange.changeId);
      console.log('Rollback validation:', validation);

      // Perform rollback
      const rollbackResult = await rollbackService.rollbackChange(firstChange.changeId);

      expect(rollbackResult.success).toBe(true);
      expect(rollbackResult.filesRestored.length).toBeGreaterThan(0);
      expect(rollbackResult.errors).toEqual([]);

      console.log('Rollback completed:', rollbackResult);
    }
  });

  it('should verify file was restored', async () => {
    const firstChange = executionResult.changes[0] as FileChange;

    if (firstChange.changeId && firstChange.oldContent) {
      // Read the file to verify it was restored
      const response = await fetch(
        `http://localhost:3000/api/files/${encodeURIComponent(firstChange.path)}`
      );

      expect(response.ok).toBe(true);
      const file = await response.json();

      // File should contain the old content
      expect(file.content).toContain(firstChange.oldContent.substring(0, 50));

      console.log('File restored successfully');
    }
  });

  it('should report accurate statistics', () => {
    const stats = orchestrator.getStatistics();

    expect(stats.totalExecutions).toBeGreaterThan(0);
    expect(stats.completedExecutions).toBeGreaterThan(0);
    expect(stats.averageExecutionTime).toBeGreaterThan(0);

    console.log('Orchestrator statistics:', stats);
  });

  afterAll(() => {
    orchestrator.shutdown();
    console.log('Test cleanup completed');
  });
});

