const mockData: GraphData = {
  nodes: [
    { id: '1', group: 1, label: 'Node 1', type: 'entry' },
    { id: '2', group: 1, label: 'Node 2', type: 'logic' },
    { id: '3', group: 1, label: 'Node 3', type: 'storage' },
    { id: '4', group: 1, label: 'Node 4', type: 'exit' }
  ],
  links: [
    { source: '1', target: '2', value: 1 },
    { source: '2', target: '3', value: 1 },
    { source: '3', target: '4', value: 1 }
  ]
};

describe('FocusMode', () => {
  it('renders all data when no node is focused', () => {
    const renderSpy = jest.fn();
    render(
      <FocusMode
        data={mockData}
        selectedNodeId={null}
        onClearFocus={() => {}}
      >
        {(data) => {
          renderSpy(data);
          return <div>{data.nodes.length} nodes</div>;
        }}
      </FocusMode>
    );

    expect(renderSpy).toHaveBeenCalledWith(mockData);
    expect(screen.getByText('4 nodes')).toBeInTheDocument();
  });

  it('filters to focused node and its dependencies', () => {
    const renderSpy = jest.fn();
    render(
      <FocusMode
        data={mockData}
        selectedNodeId="2"
        onClearFocus={() => {}}
      >
        {(data) => {
          renderSpy(data);
          return <div>{data.nodes.length} nodes</div>;
        }}
      </FocusMode>
    );

    const filteredData = renderSpy.mock.calls[0][0] as GraphData;
    expect(filteredData.nodes).toHaveLength(3); // Node 2, plus 1 and 3 (connected)
    expect(filteredData.nodes.map(n => n.id).sort()).toEqual(['1', '2', '3']);
  });

  it('filters links to only those between visible nodes', () => {
    const renderSpy = jest.fn();
    render(
      <FocusMode
        data={mockData}
        selectedNodeId="2"
        onClearFocus={() => {}}
      >
        {(data) => {
          renderSpy(data);
          return null;
        }}
      </FocusMode>
    );

    const filteredData = renderSpy.mock.calls[0][0] as GraphData;
    expect(filteredData.links).toHaveLength(2); // 1->2 and 2->3 only
  });

  it('displays focus mode banner when focused', () => {
    render(
      <FocusMode
        data={mockData}
        selectedNodeId="2"
        onClearFocus={() => {}}
      >
        {(data) => <div>{data.nodes.length} nodes</div>}
      </FocusMode>
    );

    expect(screen.getByText(/Focus:/)).toBeInTheDocument();
    expect(screen.getByText('Node 2')).toBeInTheDocument();
  });

  it('calls onClearFocus when clear button is clicked', () => {
    const clearSpy = jest.fn();
    render(
      <FocusMode
        data={mockData}
        selectedNodeId="2"
        onClearFocus={clearSpy}
      >
        {(data) => <div>{data.nodes.length} nodes</div>}
      </FocusMode>
    );

    const clearButton = screen.getByText(/Clear/);
    fireEvent.click(clearButton);

    expect(clearSpy).toHaveBeenCalled();
  });

  it('shows count of hidden nodes', () => {
    render(
      <FocusMode
        data={mockData}
        selectedNodeId="2"
        onClearFocus={() => {}}
      >
        {(data) => <div>{data.nodes.length} nodes</div>}
      </FocusMode>
    );

    expect(screen.getByText(/1 nodes hidden/)).toBeInTheDocument();
  });

  it('handles nodes with no connections gracefully', () => {
    const isolatedData: GraphData = {
      nodes: [
        { id: '1', group: 1, label: 'Node 1', type: 'entry' },
        { id: '2', group: 1, label: 'Isolated', type: 'logic' }
      ],
      links: []
    };

    const renderSpy = jest.fn();
    render(
      <FocusMode
        data={isolatedData}
        selectedNodeId="1"
        onClearFocus={() => {}}
      >
        {(data) => {
          renderSpy(data);
          return null;
        }}
      </FocusMode>
    );

    const filteredData = renderSpy.mock.calls[0][0] as GraphData;
    expect(filteredData.nodes).toHaveLength(1); // Only node 1
    expect(filteredData.links).toHaveLength(0);
  });
});

/**
 * useTaskExecution.ts - Hook for managing task execution with subagent
 *
 * Features:
 * - Execute tasks through subagent orchestrator
 * - Track execution status and progress
 * - Handle rollback of completed tasks
 * - Real-time updates via callbacks
 */

import { useState, useCallback, useEffect } from 'react';
import type { Task } from '../types/task';
import type { ExecutionResult } from '../types/subagent';
import { getOrchestrator } from '../services/subagentOrchestrator';
import { getRollbackService } from '../services/rollbackService';

export interface TaskExecutionState {
  executionId: string | null;
  status: 'idle' | 'running' | 'completed' | 'failed' | 'rolling_back';
  progress: number;
  error: string | null;
  result: ExecutionResult | null;
}

export function useTaskExecution() {
  const [state, setState] = useState<TaskExecutionState>({
    executionId: null,
    status: 'idle',
    progress: 0,
    error: null,
    result: null,
  });

  const [taskExecutions, setTaskExecutions] = useState<Map<string, string>>(new Map());

  // Subscribe to execution events
  useEffect(() => {
    const orchestrator = getOrchestrator();

    const unsubscribe = orchestrator.onEvent((event) => {
      if (event.executionId === state.executionId) {
        const result = orchestrator.getExecution(event.executionId);

        if (result) {
          setState(prev => ({
            ...prev,
            result,
            status: result.status === 'completed'
              ? 'completed'
              : result.status === 'failed'
              ? 'failed'
              : prev.status,
            progress: result.progress,
            error: result.error?.message || null,
          }));
        }
      }
    });

    return unsubscribe;
  }, [state.executionId]);

  // Execute a task
  const executeTask = useCallback(async (task: Task) => {
    try {
      setState({
        executionId: null,
        status: 'running',
        progress: 0,
        error: null,
        result: null,
      });

      const orchestrator = getOrchestrator();
      const executionId = await orchestrator.submit({
        taskId: task.id,
        taskTitle: task.title,
        taskDescription: task.description || '',
        files: task.files,
        priority: task.priority,
      });

      setTaskExecutions(prev => new Map(prev).set(task.id, executionId));

      setState(prev => ({
        ...prev,
        executionId,
      }));

      return executionId;
    } catch (error) {
      setState(prev => ({
        ...prev,
        status: 'failed',
        error: error instanceof Error ? error.message : 'Failed to execute task',
      }));
      return null;
    }
  }, []);

  // Undo a task execution
  const undoTask = useCallback(async (task: Task) => {
    const executionId = taskExecutions.get(task.id);

    if (!executionId) {
      setState(prev => ({
        ...prev,
        error: 'No execution found for this task',
      }));
      return false;
    }

    try {
      setState(prev => ({
        ...prev,
        status: 'rolling_back',
      }));

      const orchestrator = getOrchestrator();
      const execution = orchestrator.getExecution(executionId);

      if (!execution || execution.changes.length === 0) {
        setState(prev => ({
          ...prev,
          status: 'idle',
          error: 'No changes to rollback',
        }));
        return false;
      }

      const rollbackService = getRollbackService();
      const result = await rollbackService.rollbackExecution(executionId, execution.changes);

      if (result.success) {
        setState({
          executionId: null,
          status: 'idle',
          progress: 0,
          error: null,
          result: null,
        });
        return true;
      } else {
        setState(prev => ({
          ...prev,
          status: 'idle',
          error: result.errors.join(', '),
        }));
        return false;
      }
    } catch (error) {
      setState(prev => ({
        ...prev,
        status: 'idle',
        error: error instanceof Error ? error.message : 'Rollback failed',
      }));
      return false;
    }
  }, [taskExecutions]);

  // Get execution status for a task
  const getTaskExecutionStatus = useCallback((taskId: string) => {
    const executionId = taskExecutions.get(taskId);
    if (!executionId) return 'idle';

    const orchestrator = getOrchestrator();
    const execution = orchestrator.getExecution(executionId);

    return execution?.status || 'idle';
  }, [taskExecutions]);

  // Cancel a running execution
  const cancelExecution = useCallback((taskId: string) => {
    const executionId = taskExecutions.get(taskId);
    if (executionId) {
      const orchestrator = getOrchestrator();
      return orchestrator.cancel(executionId);
    }
    return false;
  }, [taskExecutions]);

  // Clear error state
  const clearError = useCallback(() => {
    setState(prev => ({
      ...prev,
      error: null,
    }));
  }, []);

  return {
    state,
    executeTask,
    undoTask,
    getTaskExecutionStatus,
    cancelExecution,
    clearError,
  };
}

/**
 * SearchIndexer Tests
 */

import { SearchIndexer, getSearchIndexer, resetSearchIndexer } from './searchIndexer';
import { GraphData } from '../types';

describe('SearchIndexer', () => {
  let indexer: SearchIndexer;
  let mockData: GraphData;

  beforeEach(() => {
    indexer = new SearchIndexer();
    resetSearchIndexer();

    mockData = {
      nodes: [
        { id: '1', group: 1, label: 'UserAuth', type: 'entry' },
        { id: '2', group: 1, label: 'DatabaseService', type: 'storage' },
        { id: '3', group: 1, label: 'APIGateway', type: 'logic' },
        { id: '4', group: 1, label: 'ResponseHandler', type: 'exit' }
      ],
      links: [
        { source: '1', target: '3', value: 1, label: 'authenticates' },
        { source: '3', target: '2', value: 1, label: 'queries' },
        { source: '2', target: '4', value: 1, label: 'returns data' }
      ]
    };
  });

  describe('buildIndex', () => {
    it('builds index from graph data', () => {
      indexer.buildIndex(mockData);

      expect(indexer.getAllLabels()).toContain('UserAuth');
      expect(indexer.getAllLabels()).toContain('DatabaseService');
      expect(indexer.getAllLabels()).toContain('authenticates');
    });

    it('clears existing index when building new one', () => {
      indexer.buildIndex(mockData);
      expect(indexer.getAllLabels().length).toBeGreaterThan(0);

      const emptyData: GraphData = { nodes: [], links: [] };
      indexer.buildIndex(emptyData);

      expect(indexer.getAllLabels()).toHaveLength(0);
    });
  });

  describe('search', () => {
    beforeEach(() => {
      indexer.buildIndex(mockData);
    });

    it('returns empty array for empty query', () => {
      const results = indexer.search('');
      expect(results).toHaveLength(0);
    });

    it('finds exact matches', () => {
      const results = indexer.search('UserAuth');
      expect(results).toHaveLength(1);
      expect(results[0].label).toBe('UserAuth');
      expect(results[0].score).toBeGreaterThan(50);
    });

    it('finds partial matches', () => {
      const results = indexer.search('auth');
      expect(results.length).toBeGreaterThan(0);
      expect(results.some(r => r.label.includes('auth'))).toBe(true);
    });

    it('searches link labels', () => {
      const results = indexer.search('authenticates');
      expect(results.length).toBeGreaterThan(0);
      expect(results.some(r => r.label === 'authenticates')).toBe(true);
    });

    it('sorts results by relevance score', () => {
      const results = indexer.search('Service');
      expect(results).toHaveLength(1);

      for (let i = 1; i < results.length; i++) {
        expect(results[i - 1].score).toBeGreaterThanOrEqual(results[i].score);
      }
    });

    it('returns empty array when no matches found', () => {
      const results = indexer.search('NonExistent');
      expect(results).toHaveLength(0);
    });

    it('is case-insensitive', () => {
      const lowerResults = indexer.search('userauth');
      const upperResults = indexer.search('USERAUTH');
      const mixedResults = indexer.search('UsErAuTh');

      expect(lowerResults.length).toBeGreaterThan(0);
      expect(upperResults.length).toBeGreaterThan(0);
      expect(mixedResults.length).toBeGreaterThan(0);
    });
  });

  describe('getNode', () => {
    beforeEach(() => {
      indexer.buildIndex(mockData);
    });

    it('returns node by ID', () => {
      const node = indexer.getNode('1');
      expect(node).toBeDefined();
      expect(node?.label).toBe('UserAuth');
    });

    it('returns undefined for non-existent node', () => {
      const node = indexer.getNode('999');
      expect(node).toBeUndefined();
    });
  });

  describe('getAllLabels', () => {
    beforeEach(() => {
      indexer.buildIndex(mockData);
    });

    it('returns all node and link labels', () => {
      const labels = indexer.getAllLabels();
      expect(labels).toContain('UserAuth');
      expect(labels).toContain('DatabaseService');
      expect(labels).toContain('authenticates');
      expect(labels).toContain('queries');
    });
  });

  describe('Global instance', () => {
    it('returns singleton instance', () => {
      const instance1 = getSearchIndexer();
      const instance2 = getSearchIndexer();

      expect(instance1).toBe(instance2);
    });

    it('can be reset', () => {
      const instance1 = getSearchIndexer();
      resetSearchIndexer();
      const instance2 = getSearchIndexer();

      expect(instance1).not.toBe(instance2);
    });
  });

  describe('Relevance scoring', () => {
    beforeEach(() => {
      indexer.buildIndex(mockData);
    });

    it('gives highest score to exact label match', () => {
      const results = indexer.search('UserAuth');
      expect(results[0].score).toBe(100);
    });

    it('gives high score to prefix match', () => {
      const results = indexer.search('User');
      expect(results[0].score).toBe(50);
    });

    it('gives medium score to contains match', () => {
      const results = indexer.search('vice');
      expect(results[0].score).toBe(25);
    });

    it('gives bonus for type match', () => {
      const results = indexer.search('storage');
      expect(results.some(r => r.description?.includes('storage'))).toBe(true);
    });
  });
});

#!/usr/bin/env tsx
/**
 * Manual test: Verify rollback functionality
 *
 * Prerequisites:
 * 1. Start the server: npm run server
 * 2. Run this script: npx tsx tests/manual/testRollback.ts
 *
 * This test:
 * 1. Creates a test file
 * 2. Writes content to it
 * 3. Modifies the content
 * 4. Verifies the change was recorded
 * 5. Rolls back the change
 * 6. Verifies the original content was restored
 */

import { randomUUID } from 'crypto';

const API_BASE = 'http://localhost:3000/api';

async function testRollback() {
  console.log('Starting rollback test...\n');

  const testFilePath = `test-${randomUUID()}.txt`;
  const originalContent = 'Original content\nLine 2\nLine 3';
  const modifiedContent = 'Modified content\nLine 2\nLine 3\nLine 4';

  try {
    // Step 1: Create initial file
    console.log('Step 1: Creating test file...');
    const createResponse = await fetch(`${API_BASE}/files/${testFilePath}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ content: originalContent }),
    });

    if (!createResponse.ok) {
      throw new Error('Failed to create file');
    }
    console.log('✓ File created\n');

    // Step 2: Verify initial content
    console.log('Step 2: Verifying initial content...');
    const readResponse1 = await fetch(`${API_BASE}/files/${testFilePath}`);
    const file1 = await readResponse1.json();

    if (file1.content !== originalContent) {
      throw new Error('Initial content mismatch');
    }
    console.log('✓ Initial content verified\n');

    // Step 3: Modify file
    console.log('Step 3: Modifying file...');
    const modifyResponse = await fetch(`${API_BASE}/files/${testFilePath}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ content: modifiedContent }),
    });

    if (!modifyResponse.ok) {
      throw new Error('Failed to modify file');
    }
    console.log('✓ File modified\n');

    // Step 4: Get all changes and find the modification
    console.log('Step 4: Retrieving change journal...');
    const changesResponse = await fetch(`${API_BASE}/changes`);
    const changesData = await changesResponse.json();

    const modifyChange = changesData.changes.find(
      (c: any) => c.path === testFilePath && c.newContent === modifiedContent
    );

    if (!modifyChange) {
      throw new Error('Change not found in journal');
    }
    console.log(`✓ Found change: ${modifyChange.id}`);
    console.log(`  Old content: ${modifyChange.oldContent?.substring(0, 30)}...`);
    console.log(`  New content: ${modifyChange.newContent?.substring(0, 30)}...\n`);

    // Step 5: Verify modified content
    console.log('Step 5: Verifying modified content...');
    const readResponse2 = await fetch(`${API_BASE}/files/${testFilePath}`);
    const file2 = await readResponse2.json();

    if (file2.content !== modifiedContent) {
      throw new Error('Modified content mismatch');
    }
    console.log('✓ Modified content verified\n');

    // Step 6: Rollback the change
    console.log('Step 6: Rolling back change...');
    const rollbackResponse = await fetch(
      `${API_BASE}/changes/${modifyChange.id}/rollback`,
      { method: 'POST' }
    );

    if (!rollbackResponse.ok) {
      throw new Error('Failed to rollback');
    }
    const rollbackData = await rollbackResponse.json();
    console.log(`✓ Rollback successful: ${rollbackData.message}\n`);

    // Step 7: Verify original content was restored
    console.log('Step 7: Verifying rollback...');
    const readResponse3 = await fetch(`${API_BASE}/files/${testFilePath}`);
    const file3 = await readResponse3.json();

    if (file3.content !== originalContent) {
      console.error('Expected:', originalContent);
      console.error('Got:', file3.content);
      throw new Error('Rollback failed - content not restored');
    }
    console.log('✓ Original content restored!\n');

    // Cleanup
    console.log('Cleaning up...');
    await fetch(`${API_BASE}/files/${testFilePath}`, { method: 'DELETE' });
    console.log('✓ Test file deleted\n');

    console.log('✅ All tests passed!');
  } catch (error) {
    console.error('❌ Test failed:', error);
    process.exit(1);
  }
}

// Run the test
testRollback();

/**
