    const shortcuts = [
      {
        key: 'k',
        metaKey: true,
        handler: mockHandlers.onOpenQuickActions
      },
      {
        key: 'f',
        metaKey: true,
        handler: mockHandlers.onFocusNode
      },
      {
        key: 'Escape',
        handler: mockHandlers.onCloseModals
      }
    ];

    renderHook(() => useKeyboardShortcuts(shortcuts, true));

    expect(shortcuts).toHaveLength(3);
